window.RTLBenchLSData.register("assets/3b4396009bd052f5e365ff893824468ceedce8f2a27f4a344ea266b5c29fa365.txt","// Copyright lowRISC contributors.\n// Copyright 2017 ETH Zurich and University of Bologna, see also CREDITS.md.\n// Licensed under the Apache License, Version 2.0, see LICENSE for details.\n// SPDX-License-Identifier: Apache-2.0\n/**\n * Package with constants used by Ibex\n */\npackage ibex_pkg;\n/////////////\n// Opcodes //\n/////////////\ntypedef enum logic [6:0] {\n  OPCODE_LOAD     = 7'h03,\n  OPCODE_MISC_MEM = 7'h0f,\n  OPCODE_OP_IMM   = 7'h13,\n  OPCODE_AUIPC    = 7'h17,\n  OPCODE_STORE    = 7'h23,\n  OPCODE_OP       = 7'h33,\n  OPCODE_LUI      = 7'h37,\n  OPCODE_BRANCH   = 7'h63,\n  OPCODE_JALR     = 7'h67,\n  OPCODE_JAL      = 7'h6f,\n  OPCODE_SYSTEM   = 7'h73\n} opcode_e;\n////////////////////\n// ALU operations //\n////////////////////\ntypedef enum logic [5:0] {\n  // Arithmetics\n  ALU_ADD,\n  ALU_SUB,\n  // Logics\n  ALU_XOR,\n  ALU_OR,\n  ALU_AND,\n  // RV32B\n  ALU_XNOR,\n  ALU_ORN,\n  ALU_ANDN,\n  // Shifts\n  ALU_SRA,\n  ALU_SRL,\n  ALU_SLL,\n  // RV32B\n  ALU_SRO,\n  ALU_SLO,\n  ALU_ROR,\n  ALU_ROL,\n  ALU_GREV,\n  ALU_GORC,\n  ALU_SHFL,\n  ALU_UNSHFL,\n  // Comparisons\n  ALU_LT,\n  ALU_LTU,\n  ALU_GE,\n  ALU_GEU,\n  ALU_EQ,\n  ALU_NE,\n  // RV32B\n  ALU_MIN,\n  ALU_MINU,\n  ALU_MAX,\n  ALU_MAXU,\n  // Pack\n  // RV32B\n  ALU_PACK,\n  ALU_PACKU,\n  ALU_PACKH,\n  // Sign-Extend\n  // RV32B\n  ALU_SEXTB,\n  ALU_SEXTH,\n  // Bitcounting\n  // RV32B\n  ALU_CLZ,\n  ALU_CTZ,\n  ALU_PCNT,\n  // Set lower than\n  ALU_SLT,\n  ALU_SLTU,\n  // Ternary Bitmanip Operations\n  // RV32B\n  ALU_CMOV,\n  ALU_CMIX,\n  ALU_FSL,\n  ALU_FSR,\n  // Single-Bit Operations\n  // RV32B\n  ALU_SBSET,\n  ALU_SBCLR,\n  ALU_SBINV,\n  ALU_SBEXT,\n  // Bit Extract / Deposit\n  // RV32B\n  ALU_BEXT,\n  ALU_BDEP,\n  // Bit Field Place\n  // RV32B\n  ALU_BFP,\n  // Carry-less Multiply\n  // RV32B\n  ALU_CLMUL,\n  ALU_CLMULR,\n  ALU_CLMULH,\n  // Cyclic Redundancy Check\n  ALU_CRC32_B,\n  ALU_CRC32C_B,\n  ALU_CRC32_H,\n  ALU_CRC32C_H,\n  ALU_CRC32_W,\n  ALU_CRC32C_W\n} alu_op_e;\ntypedef enum logic [1:0] {\n  // Multiplier/divider\n  MD_OP_MULL,\n  MD_OP_MULH,\n  MD_OP_DIV,\n  MD_OP_REM\n} md_op_e;\n//////////////////////////////////\n// Control and status registers //\n//////////////////////////////////\n// CSR operations\ntypedef enum logic [1:0] {\n  CSR_OP_READ,\n  CSR_OP_WRITE,\n  CSR_OP_SET,\n  CSR_OP_CLEAR\n} csr_op_e;\n// Privileged mode\ntypedef enum logic[1:0] {\n  PRIV_LVL_M = 2'b11,\n  PRIV_LVL_H = 2'b10,\n  PRIV_LVL_S = 2'b01,\n  PRIV_LVL_U = 2'b00\n} priv_lvl_e;\n// Constants for the dcsr.xdebugver fields\ntypedef enum logic[3:0] {\n   XDEBUGVER_NO     = 4'd0, // no external debug support\n   XDEBUGVER_STD    = 4'd4, // external debug according to RISC-V debug spec\n   XDEBUGVER_NONSTD = 4'd15 // debug not conforming to RISC-V debug spec\n} x_debug_ver_e;\n//////////////\n// WB stage //\n//////////////\n// Type of instruction present in writeback stage\ntypedef enum logic[1:0] {\n  WB_INSTR_LOAD,  // Instruction is awaiting load data\n  WB_INSTR_STORE, // Instruction is awaiting store response\n  WB_INSTR_OTHER  // Instruction doesn't fit into above categories\n} wb_instr_type_e;\n//////////////\n// ID stage //\n//////////////\n// Operand a selection\ntypedef enum logic[1:0] {\n  OP_A_REG_A,\n  OP_A_FWD,\n  OP_A_CURRPC,\n  OP_A_IMM\n} op_a_sel_e;\n// Immediate a selection\ntypedef enum logic {\n  IMM_A_Z,\n  IMM_A_ZERO\n} imm_a_sel_e;\n// Operand b selection\ntypedef enum logic {\n  OP_B_REG_B,\n  OP_B_IMM\n} op_b_sel_e;\n// Immediate b selection\ntypedef enum logic [2:0] {\n  IMM_B_I,\n  IMM_B_S,\n  IMM_B_B,\n  IMM_B_U,\n  IMM_B_J,\n  IMM_B_INCR_PC,\n  IMM_B_INCR_ADDR\n} imm_b_sel_e;\n// Regfile write data selection\ntypedef enum logic {\n  RF_WD_EX,\n  RF_WD_CSR\n} rf_wd_sel_e;\n//////////////\n// IF stage //\n//////////////\n// PC mux selection\ntypedef enum logic [2:0] {\n  PC_BOOT,\n  PC_JUMP,\n  PC_EXC,\n  PC_ERET,\n  PC_DRET\n} pc_sel_e;\n// Exception PC mux selection\ntypedef enum logic [1:0] {\n  EXC_PC_EXC,\n  EXC_PC_IRQ,\n  EXC_PC_DBD,\n  EXC_PC_DBG_EXC // Exception while in debug mode\n} exc_pc_sel_e;\n// Interrupt requests\ntypedef struct packed {\n  logic        irq_software;\n  logic        irq_timer;\n  logic        irq_external;\n  logic [14:0] irq_fast; // 15 fast interrupts,\n                         // one interrupt is reserved for NMI (not visible through mip/mie)\n} irqs_t;\n// Exception cause\ntypedef enum logic [5:0] {\n  EXC_CAUSE_IRQ_SOFTWARE_M     = {1'b1, 5'd03},\n  EXC_CAUSE_IRQ_TIMER_M        = {1'b1, 5'd07},\n  EXC_CAUSE_IRQ_EXTERNAL_M     = {1'b1, 5'd11},\n  // EXC_CAUSE_IRQ_FAST_0      = {1'b1, 5'd16},\n  // EXC_CAUSE_IRQ_FAST_14     = {1'b1, 5'd30},\n  EXC_CAUSE_IRQ_NM             = {1'b1, 5'd31}, // == EXC_CAUSE_IRQ_FAST_15\n  EXC_CAUSE_INSN_ADDR_MISA     = {1'b0, 5'd00},\n  EXC_CAUSE_INSTR_ACCESS_FAULT = {1'b0, 5'd01},\n  EXC_CAUSE_ILLEGAL_INSN       = {1'b0, 5'd02},\n  EXC_CAUSE_BREAKPOINT         = {1'b0, 5'd03},\n  EXC_CAUSE_LOAD_ACCESS_FAULT  = {1'b0, 5'd05},\n  EXC_CAUSE_STORE_ACCESS_FAULT = {1'b0, 5'd07},\n  EXC_CAUSE_ECALL_UMODE        = {1'b0, 5'd08},\n  EXC_CAUSE_ECALL_MMODE        = {1'b0, 5'd11}\n} exc_cause_e;\n// Debug cause\ntypedef enum logic [2:0] {\n  DBG_CAUSE_NONE    = 3'h0,\n  DBG_CAUSE_EBREAK  = 3'h1,\n  DBG_CAUSE_TRIGGER = 3'h2,\n  DBG_CAUSE_HALTREQ = 3'h3,\n  DBG_CAUSE_STEP    = 3'h4\n} dbg_cause_e;\n// PMP constants\nparameter int unsigned PMP_MAX_REGIONS      = 16;\nparameter int unsigned PMP_CFG_W            = 8;\n// PMP acces type\nparameter int unsigned PMP_I = 0;\nparameter int unsigned PMP_D = 1;\ntypedef enum logic [1:0] {\n  PMP_ACC_EXEC    = 2'b00,\n  PMP_ACC_WRITE   = 2'b01,\n  PMP_ACC_READ    = 2'b10\n} pmp_req_e;\n// PMP cfg structures\ntypedef enum logic [1:0] {\n  PMP_MODE_OFF   = 2'b00,\n  PMP_MODE_TOR   = 2'b01,\n  PMP_MODE_NA4   = 2'b10,\n  PMP_MODE_NAPOT = 2'b11\n} pmp_cfg_mode_e;\ntypedef struct packed {\n  logic          lock;\n  pmp_cfg_mode_e mode;\n  logic          exec;\n  logic          write;\n  logic          read;\n} pmp_cfg_t;\n// CSRs\ntypedef enum logic[11:0] {\n  // Machine information\n  CSR_MHARTID   = 12'hF14,\n  // Machine trap setup\n  CSR_MSTATUS   = 12'h300,\n  CSR_MISA      = 12'h301,\n  CSR_MIE       = 12'h304,\n  CSR_MTVEC     = 12'h305,\n  // Machine trap handling\n  CSR_MSCRATCH  = 12'h340,\n  CSR_MEPC      = 12'h341,\n  CSR_MCAUSE    = 12'h342,\n  CSR_MTVAL     = 12'h343,\n  CSR_MIP       = 12'h344,\n  // Physical memory protection\n  CSR_PMPCFG0   = 12'h3A0,\n  CSR_PMPCFG1   = 12'h3A1,\n  CSR_PMPCFG2   = 12'h3A2,\n  CSR_PMPCFG3   = 12'h3A3,\n  CSR_PMPADDR0  = 12'h3B0,\n  CSR_PMPADDR1  = 12'h3B1,\n  CSR_PMPADDR2  = 12'h3B2,\n  CSR_PMPADDR3  = 12'h3B3,\n  CSR_PMPADDR4  = 12'h3B4,\n  CSR_PMPADDR5  = 12'h3B5,\n  CSR_PMPADDR6  = 12'h3B6,\n  CSR_PMPADDR7  = 12'h3B7,\n  CSR_PMPADDR8  = 12'h3B8,\n  CSR_PMPADDR9  = 12'h3B9,\n  CSR_PMPADDR10 = 12'h3BA,\n  CSR_PMPADDR11 = 12'h3BB,\n  CSR_PMPADDR12 = 12'h3BC,\n  CSR_PMPADDR13 = 12'h3BD,\n  CSR_PMPADDR14 = 12'h3BE,\n  CSR_PMPADDR15 = 12'h3BF,\n  // Debug trigger\n  CSR_TSELECT   = 12'h7A0,\n  CSR_TDATA1    = 12'h7A1,\n  CSR_TDATA2    = 12'h7A2,\n  CSR_TDATA3    = 12'h7A3,\n  CSR_MCONTEXT  = 12'h7A8,\n  CSR_SCONTEXT  = 12'h7AA,\n  // Debug/trace\n  CSR_DCSR      = 12'h7b0,\n  CSR_DPC       = 12'h7b1,\n  // Debug\n  CSR_DSCRATCH0 = 12'h7b2, // optional\n  CSR_DSCRATCH1 = 12'h7b3, // optional\n  // Machine Counter/Timers\n  CSR_MCOUNTINHIBIT  = 12'h320,\n  CSR_MHPMEVENT3     = 12'h323,\n  CSR_MHPMEVENT4     = 12'h324,\n  CSR_MHPMEVENT5     = 12'h325,\n  CSR_MHPMEVENT6     = 12'h326,\n  CSR_MHPMEVENT7     = 12'h327,\n  CSR_MHPMEVENT8     = 12'h328,\n  CSR_MHPMEVENT9     = 12'h329,\n  CSR_MHPMEVENT10    = 12'h32A,\n  CSR_MHPMEVENT11    = 12'h32B,\n  CSR_MHPMEVENT12    = 12'h32C,\n  CSR_MHPMEVENT13    = 12'h32D,\n  CSR_MHPMEVENT14    = 12'h32E,\n  CSR_MHPMEVENT15    = 12'h32F,\n  CSR_MHPMEVENT16    = 12'h330,\n  CSR_MHPMEVENT17    = 12'h331,\n  CSR_MHPMEVENT18    = 12'h332,\n  CSR_MHPMEVENT19    = 12'h333,\n  CSR_MHPMEVENT20    = 12'h334,\n  CSR_MHPMEVENT21    = 12'h335,\n  CSR_MHPMEVENT22    = 12'h336,\n  CSR_MHPMEVENT23    = 12'h337,\n  CSR_MHPMEVENT24    = 12'h338,\n  CSR_MHPMEVENT25    = 12'h339,\n  CSR_MHPMEVENT26    = 12'h33A,\n  CSR_MHPMEVENT27    = 12'h33B,\n  CSR_MHPMEVENT28    = 12'h33C,\n  CSR_MHPMEVENT29    = 12'h33D,\n  CSR_MHPMEVENT30    = 12'h33E,\n  CSR_MHPMEVENT31    = 12'h33F,\n  CSR_MCYCLE         = 12'hB00,\n  CSR_MINSTRET       = 12'hB02,\n  CSR_MHPMCOUNTER3   = 12'hB03,\n  CSR_MHPMCOUNTER4   = 12'hB04,\n  CSR_MHPMCOUNTER5   = 12'hB05,\n  CSR_MHPMCOUNTER6   = 12'hB06,\n  CSR_MHPMCOUNTER7   = 12'hB07,\n  CSR_MHPMCOUNTER8   = 12'hB08,\n  CSR_MHPMCOUNTER9   = 12'hB09,\n  CSR_MHPMCOUNTER10  = 12'hB0A,\n  CSR_MHPMCOUNTER11  = 12'hB0B,\n  CSR_MHPMCOUNTER12  = 12'hB0C,\n  CSR_MHPMCOUNTER13  = 12'hB0D,\n  CSR_MHPMCOUNTER14  = 12'hB0E,\n  CSR_MHPMCOUNTER15  = 12'hB0F,\n  CSR_MHPMCOUNTER16  = 12'hB10,\n  CSR_MHPMCOUNTER17  = 12'hB11,\n  CSR_MHPMCOUNTER18  = 12'hB12,\n  CSR_MHPMCOUNTER19  = 12'hB13,\n  CSR_MHPMCOUNTER20  = 12'hB14,\n  CSR_MHPMCOUNTER21  = 12'hB15,\n  CSR_MHPMCOUNTER22  = 12'hB16,\n  CSR_MHPMCOUNTER23  = 12'hB17,\n  CSR_MHPMCOUNTER24  = 12'hB18,\n  CSR_MHPMCOUNTER25  = 12'hB19,\n  CSR_MHPMCOUNTER26  = 12'hB1A,\n  CSR_MHPMCOUNTER27  = 12'hB1B,\n  CSR_MHPMCOUNTER28  = 12'hB1C,\n  CSR_MHPMCOUNTER29  = 12'hB1D,\n  CSR_MHPMCOUNTER30  = 12'hB1E,\n  CSR_MHPMCOUNTER31  = 12'hB1F,\n  CSR_MCYCLEH        = 12'hB80,\n  CSR_MINSTRETH      = 12'hB82,\n  CSR_MHPMCOUNTER3H  = 12'hB83,\n  CSR_MHPMCOUNTER4H  = 12'hB84,\n  CSR_MHPMCOUNTER5H  = 12'hB85,\n  CSR_MHPMCOUNTER6H  = 12'hB86,\n  CSR_MHPMCOUNTER7H  = 12'hB87,\n  CSR_MHPMCOUNTER8H  = 12'hB88,\n  CSR_MHPMCOUNTER9H  = 12'hB89,\n  CSR_MHPMCOUNTER10H = 12'hB8A,\n  CSR_MHPMCOUNTER11H = 12'hB8B,\n  CSR_MHPMCOUNTER12H = 12'hB8C,\n  CSR_MHPMCOUNTER13H = 12'hB8D,\n  CSR_MHPMCOUNTER14H = 12'hB8E,\n  CSR_MHPMCOUNTER15H = 12'hB8F,\n  CSR_MHPMCOUNTER16H = 12'hB90,\n  CSR_MHPMCOUNTER17H = 12'hB91,\n  CSR_MHPMCOUNTER18H = 12'hB92,\n  CSR_MHPMCOUNTER19H = 12'hB93,\n  CSR_MHPMCOUNTER20H = 12'hB94,\n  CSR_MHPMCOUNTER21H = 12'hB95,\n  CSR_MHPMCOUNTER22H = 12'hB96,\n  CSR_MHPMCOUNTER23H = 12'hB97,\n  CSR_MHPMCOUNTER24H = 12'hB98,\n  CSR_MHPMCOUNTER25H = 12'hB99,\n  CSR_MHPMCOUNTER26H = 12'hB9A,\n  CSR_MHPMCOUNTER27H = 12'hB9B,\n  CSR_MHPMCOUNTER28H = 12'hB9C,\n  CSR_MHPMCOUNTER29H = 12'hB9D,\n  CSR_MHPMCOUNTER30H = 12'hB9E,\n  CSR_MHPMCOUNTER31H = 12'hB9F,\n  CSR_CPUCTRL        = 12'h7C0,\n  CSR_SECURESEED     = 12'h7C1\n} csr_num_e;\n// CSR pmp-related offsets\nparameter logic [11:0] CSR_OFF_PMP_CFG  = 12'h3A0; // pmp_cfg  @ 12'h3a0 - 12'h3a3\nparameter logic [11:0] CSR_OFF_PMP_ADDR = 12'h3B0; // pmp_addr @ 12'h3b0 - 12'h3bf\n// CSR status bits\nparameter int unsigned CSR_MSTATUS_MIE_BIT      = 3;\nparameter int unsigned CSR_MSTATUS_MPIE_BIT     = 7;\nparameter int unsigned CSR_MSTATUS_MPP_BIT_LOW  = 11;\nparameter int unsigned CSR_MSTATUS_MPP_BIT_HIGH = 12;\nparameter int unsigned CSR_MSTATUS_MPRV_BIT     = 17;\nparameter int unsigned CSR_MSTATUS_TW_BIT       = 21;\n// CSR machine ISA\nparameter logic [1:0] CSR_MISA_MXL = 2'd1; // M-XLEN: XLEN in M-Mode for RV32\n// CSR interrupt pending/enable bits\nparameter int unsigned CSR_MSIX_BIT      = 3;\nparameter int unsigned CSR_MTIX_BIT      = 7;\nparameter int unsigned CSR_MEIX_BIT      = 11;\nparameter int unsigned CSR_MFIX_BIT_LOW  = 16;\nparameter int unsigned CSR_MFIX_BIT_HIGH = 30;\nendpackage\n// Copyright lowRISC contributors.\n// Copyright 2018 ETH Zurich and University of Bologna, see also CREDITS.md.\n// Licensed under the Apache License, Version 2.0, see LICENSE for details.\n// SPDX-License-Identifier: Apache-2.0\n// Source/Destination register instruction index\n/**\n * Instruction decoder\n *\n * This module is fully combinatorial, clock and reset are used for\n * assertions only.\n */\n// Copyright lowRISC contributors.\n// Licensed under the Apache License, Version 2.0, see LICENSE for details.\n// SPDX-License-Identifier: Apache-2.0\n// Macros and helper code for using assertions.\n//  - Provides default clk and rst options to simplify code\n//  - Provides boiler plate template for common assertions\n///////////////////\n// Helper macros //\n///////////////////\n// local helper macro to reduce code clutter. undefined at the end of this file\n// Converts an arbitrary block of code into a Verilog string\n// ASSERT_RPT is available to change the reporting mechanism when an assert fails\n///////////////////////////////////////\n// Simple assertion and cover macros //\n///////////////////////////////////////\n// Default clk and reset signals used by assertion macros below.\n// Immediate assertion\n// Note that immediate assertions are sensitive to simulation glitches.\n// Assertion in initial block. Can be used for things like parameter checking.\n// Assertion in final block. Can be used for things like queues being empty\n// at end of sim, all credits returned at end of sim, state machines in idle\n// at end of sim.\n// Assert a concurrent property directly.\n// It can be called as a module (or interface) body item.\n// Note: Above we use (__rst !== '0) in the disable iff statements instead of\n// (__rst == '1).  This properly disables the assertion in cases when reset is X at\n// the beginning of a simulation. For that case, (reset == '1) does not disable the\n// assertion.\n// Assert a concurrent property NEVER happens\n// Assert that signal has a known value (each bit is either '0' or '1') after reset.\n// It can be called as a module (or interface) body item.\n//  Cover a concurrent property\n//////////////////////////////\n// Complex assertion macros //\n//////////////////////////////\n// Assert that signal is an active-high pulse with pulse length of 1 clock cycle\n// Assert that a property is true only when an enable signal is set.  It can be called as a module\n// (or interface) body item.\n// Assert that signal has a known value (each bit is either '0' or '1') after reset if enable is\n// set.  It can be called as a module (or interface) body item.\n///////////////////////\n// Assumption macros //\n///////////////////////\n// Assume a concurrent property\n// Assume an immediate property\n//////////////////////////////////\n// For formal verification only //\n//////////////////////////////////\n// Note that the existing set of ASSERT macros specified above shall be used for FPV,\n// thereby ensuring that the assertions are evaluated during DV simulations as well.\n// ASSUME_FPV\n// Assume a concurrent property during formal verification only.\n// ASSUME_I_FPV\n// Assume a concurrent property during formal verification only.\n// COVER_FPV\n// Cover a concurrent property during formal verification\n // PRIM_ASSERT_SV\nmodule ibex_decoder #(\n    parameter bit RV32E           = 0,\n    parameter bit RV32M           = 1,\n    parameter bit RV32B           = 0,\n    parameter bit BranchTargetALU = 0\n) (\n    input  logic                 clk_i,\n    input  logic                 rst_ni,\n    // to/from controller\n    output logic                 illegal_insn_o,        // illegal instr encountered\n    output logic                 ebrk_insn_o,           // trap instr encountered\n    output logic                 mret_insn_o,           // return from exception instr\n                                                        // encountered\n    output logic                 dret_insn_o,           // return from debug instr encountered\n    output logic                 ecall_insn_o,          // syscall instr encountered\n    output logic                 wfi_insn_o,            // wait for interrupt instr encountered\n    output logic                 jump_set_o,            // jump taken set signal\n    input  logic                 branch_taken_i,        // registered branch decision\n    output logic                 icache_inval_o,\n    // from IF-ID pipeline register\n    input  logic                 instr_first_cycle_i,   // instruction read is in its first cycle\n    input  logic [31:0]          instr_rdata_i,         // instruction read from memory/cache\n    input  logic [31:0]          instr_rdata_alu_i,     // instruction read from memory/cache\n                                                        // replicated to ease fan-out)\n    input  logic                 illegal_c_insn_i,      // compressed instruction decode failed\n    // immediates\n    output ibex_pkg::imm_a_sel_e  imm_a_mux_sel_o,       // immediate selection for operand a\n    output ibex_pkg::imm_b_sel_e  imm_b_mux_sel_o,       // immediate selection for operand b\n    output ibex_pkg::op_a_sel_e   bt_a_mux_sel_o,        // branch target selection operand a\n    output ibex_pkg::imm_b_sel_e  bt_b_mux_sel_o,        // branch target selection operand b\n    output logic [31:0]           imm_i_type_o,\n    output logic [31:0]           imm_s_type_o,\n    output logic [31:0]           imm_b_type_o,\n    output logic [31:0]           imm_u_type_o,\n    output logic [31:0]           imm_j_type_o,\n    output logic [31:0]           zimm_rs1_type_o,\n    // register file\n    output ibex_pkg::rf_wd_sel_e rf_wdata_sel_o,   // RF write data selection\n    output logic                 rf_we_o,          // write enable for regfile\n    output logic [4:0]           rf_raddr_a_o,\n    output logic [4:0]           rf_raddr_b_o,\n    output logic [4:0]           rf_waddr_o,\n    output logic                 rf_ren_a_o,          // Instruction reads from RF addr A\n    output logic                 rf_ren_b_o,          // Instruction reads from RF addr B\n    // ALU\n    output ibex_pkg::alu_op_e    alu_operator_o,        // ALU operation selection\n    output ibex_pkg::op_a_sel_e  alu_op_a_mux_sel_o,    // operand a selection: reg value, PC,\n                                                        // immediate or zero\n    output ibex_pkg::op_b_sel_e  alu_op_b_mux_sel_o,    // operand b selection: reg value or\n                                                        // immediate\n    output logic                 alu_multicycle_o,      // ternary bitmanip instruction\n    // MULT & DIV\n    output logic                 mult_en_o,             // perform integer multiplication\n    output logic                 div_en_o,              // perform integer division or remainder\n    output logic                 mult_sel_o,            // as above but static, for data muxes\n    output logic                 div_sel_o,             // as above but static, for data muxes\n    output ibex_pkg::md_op_e     multdiv_operator_o,\n    output logic [1:0]           multdiv_signed_mode_o,\n    // CSRs\n    output logic                 csr_access_o,          // access to CSR\n    output ibex_pkg::csr_op_e    csr_op_o,              // operation to perform on CSR\n    // LSU\n    output logic                 data_req_o,            // start transaction to data memory\n    output logic                 data_we_o,             // write enable\n    output logic [1:0]           data_type_o,           // size of transaction: byte, half\n                                                        // word or word\n    output logic                 data_sign_extension_o, // sign extension for data read from\n                                                        // memory\n    // jump/branches\n    output logic                 jump_in_dec_o,         // jump is being calculated in ALU\n    output logic                 branch_in_dec_o\n);\n  import ibex_pkg::*;\n  logic        illegal_insn;\n  logic        illegal_reg_rv32e;\n  logic        csr_illegal;\n  logic        rf_we;\n  logic [31:0] instr;\n  logic [31:0] instr_alu;\n  logic        use_rs3;\n  csr_op_e     csr_op;\n  opcode_e     opcode;\n  opcode_e     opcode_alu;\n  // To help timing the flops containing the current instruction are replicated to reduce fan-out.\n  // instr_alu is used to determine the ALU control logic and associated operand/imm select signals\n  // as the ALU is often on the more critical timing paths. instr is used for everything else.\n  assign instr     = instr_rdata_i;\n  assign instr_alu = instr_rdata_alu_i;\n  //////////////////////////////////////\n  // Register and immediate selection //\n  //////////////////////////////////////\n  // immediate extraction and sign extension\n  assign imm_i_type_o = { {20{instr[31]}}, instr[31:20] };\n  assign imm_s_type_o = { {20{instr[31]}}, instr[31:25], instr[11:7] };\n  assign imm_b_type_o = { {19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0 };\n  assign imm_u_type_o = { instr[31:12], 12'b0 };\n  assign imm_j_type_o = { {12{instr[31]}}, instr[19:12], instr[20], instr[30:21], 1'b0 };\n  // immediate for CSR manipulation (zero extended)\n  assign zimm_rs1_type_o = { 27'b0, instr[19:15] }; // rs1\n  // source registers\n  assign rf_raddr_a_o = use_rs3 ? instr[31:27] : instr[19:15]; // rs3 / rs1\n  assign rf_raddr_b_o = instr[24:20]; // rs2\n  // destination register\n  assign rf_waddr_o   = instr[11:07]; // rd\n  ////////////////////\n  // Register check //\n  ////////////////////\n  if (RV32E) begin : gen_rv32e_reg_check_active\n    assign illegal_reg_rv32e = ((rf_raddr_a_o[4] & (alu_op_a_mux_sel_o == OP_A_REG_A)) |\n                                (rf_raddr_b_o[4] & (alu_op_b_mux_sel_o == OP_B_REG_B)) |\n                                (rf_waddr_o[4]   & rf_we));\n  end else begin : gen_rv32e_reg_check_inactive\n    assign illegal_reg_rv32e = 1'b0;\n  end\n  ///////////////////////\n  // CSR operand check //\n  ///////////////////////\n  always_comb begin : csr_operand_check\n    csr_op_o = csr_op;\n    // CSRRSI/CSRRCI must not write 0 to CSRs (uimm[4:0]=='0)\n    // CSRRS/CSRRC must not write from x0 to CSRs (rs1=='0)\n    if ((csr_op == CSR_OP_SET || csr_op == CSR_OP_CLEAR) &&\n        instr[19:15] == '0) begin\n      csr_op_o = CSR_OP_READ;\n    end\n  end\n  /////////////\n  // Decoder //\n  /////////////\n  always_comb begin\n    jump_in_dec_o         = 1'b0;\n    jump_set_o            = 1'b0;\n    branch_in_dec_o       = 1'b0;\n    icache_inval_o        = 1'b0;\n    multdiv_operator_o    = MD_OP_MULL;\n    multdiv_signed_mode_o = 2'b00;\n    rf_wdata_sel_o        = RF_WD_EX;\n    rf_we                 = 1'b0;\n    rf_ren_a_o            = 1'b0;\n    rf_ren_b_o            = 1'b0;\n    csr_access_o          = 1'b0;\n    csr_illegal           = 1'b0;\n    csr_op                = CSR_OP_READ;\n    data_we_o             = 1'b0;\n    data_type_o           = 2'b00;\n    data_sign_extension_o = 1'b0;\n    data_req_o            = 1'b0;\n    illegal_insn          = 1'b0;\n    ebrk_insn_o           = 1'b0;\n    mret_insn_o           = 1'b0;\n    dret_insn_o           = 1'b0;\n    ecall_insn_o          = 1'b0;\n    wfi_insn_o            = 1'b0;\n    opcode                = opcode_e'(instr[6:0]);\n    unique case (opcode)\n      ///////////\n      // Jumps //\n      ///////////\n      OPCODE_JAL: begin   // Jump and Link\n        jump_in_dec_o      = 1'b1;\n        if (instr_first_cycle_i) begin\n          // Calculate jump target (and store PC + 4 if BranchTargetALU is configured)\n          rf_we            = BranchTargetALU;\n          jump_set_o       = 1'b1;\n        end else begin\n          // Calculate and store PC+4\n          rf_we            = 1'b1;\n        end\n      end\n      OPCODE_JALR: begin  // Jump and Link Register\n        jump_in_dec_o      = 1'b1;\n        if (instr_first_cycle_i) begin\n          // Calculate jump target (and store PC + 4 if BranchTargetALU is configured)\n          rf_we            = BranchTargetALU;\n          jump_set_o       = 1'b1;\n        end else begin\n          // Calculate and store PC+4\n          rf_we            = 1'b1;\n        end\n        if (instr[14:12] != 3'b0) begin\n          illegal_insn = 1'b1;\n        end\n        rf_ren_a_o = 1'b1;\n      end\n      OPCODE_BRANCH: begin // Branch\n        branch_in_dec_o       = 1'b1;\n        // Check branch condition selection\n        unique case (instr[14:12])\n          3'b000,\n          3'b001,\n          3'b100,\n          3'b101,\n          3'b110,\n          3'b111:  illegal_insn = 1'b0;\n          default: illegal_insn = 1'b1;\n        endcase\n        rf_ren_a_o = 1'b1;\n        rf_ren_b_o = 1'b1;\n      end\n      ////////////////\n      // Load/store //\n      ////////////////\n      OPCODE_STORE: begin\n        rf_ren_a_o         = 1'b1;\n        rf_ren_b_o         = 1'b1;\n        data_req_o         = 1'b1;\n        data_we_o          = 1'b1;\n        if (instr[14]) begin\n          illegal_insn = 1'b1;\n        end\n        // store size\n        unique case (instr[13:12])\n          2'b00:   data_type_o  = 2'b10; // sb\n          2'b01:   data_type_o  = 2'b01; // sh\n          2'b10:   data_type_o  = 2'b00; // sw\n          default: illegal_insn = 1'b1;\n        endcase\n      end\n      OPCODE_LOAD: begin\n        rf_ren_a_o          = 1'b1;\n        data_req_o          = 1'b1;\n        data_type_o         = 2'b00;\n        // sign/zero extension\n        data_sign_extension_o = ~instr[14];\n        // load size\n        unique case (instr[13:12])\n          2'b00: data_type_o = 2'b10; // lb(u)\n          2'b01: data_type_o = 2'b01; // lh(u)\n          2'b10: begin\n            data_type_o = 2'b00;      // lw\n            if (instr[14]) begin\n              illegal_insn = 1'b1;    // lwu does not exist\n            end\n          end\n          default: begin\n            illegal_insn = 1'b1;\n          end\n        endcase\n      end\n      /////////\n      // ALU //\n      /////////\n      OPCODE_LUI: begin  // Load Upper Immediate\n        rf_we            = 1'b1;\n      end\n      OPCODE_AUIPC: begin  // Add Upper Immediate to PC\n        rf_we            = 1'b1;\n      end\n      OPCODE_OP_IMM: begin // Register-Immediate ALU Operations\n        rf_ren_a_o       = 1'b1;\n        rf_we            = 1'b1;\n        unique case (instr[14:12])\n          3'b000,\n          3'b010,\n          3'b011,\n          3'b100,\n          3'b110,\n          3'b111: illegal_insn = 1'b0;\n          3'b001: begin\n            unique case (instr[31:27])\n              5'b0_0000: illegal_insn = 1'b0;                      // slli\n              5'b0_0100,                                           // sloi\n              5'b0_1001,                                           // sbclri\n              5'b0_0101,                                           // sbseti\n              5'b0_1101: illegal_insn = RV32B ? 1'b0 : 1'b1;       // sbinvi\n              5'b0_0001: if (instr[26] == 1'b0) begin\n                illegal_insn = RV32B ? 1'b0 : 1'b1;                // shfl\n              end else begin\n                illegal_insn = 1'b1;\n              end\n              5'b0_1100: begin\n                unique case(instr[26:20])\n                  7'b000_0000,                                     // clz\n                  7'b000_0001,                                     // ctz\n                  7'b000_0010,                                     // pcnt\n                  7'b000_0100,                                     // sext.b\n                  7'b000_0101,                                     // sext.h\n                  7'b001_0000,                                     // crc32.b\n                  7'b001_0001,                                     // crc32.h\n                  7'b001_0010,                                     // crc32.w\n                  7'b001_1000,                                     // crc32c.b\n                  7'b001_1001,                                     // crc32c.h\n                  7'b001_1010: illegal_insn = RV32B ? 1'b0 : 1'b1; // crc32c.w\n                  default: illegal_insn = 1'b1;\n                endcase\n              end\n              default : illegal_insn = 1'b1;\n            endcase\n          end\n          3'b101: begin\n            if (instr[26]) begin\n              illegal_insn = RV32B ? 1'b0 : 1'b1;                  // fsri\n            end else begin\n              unique case (instr[31:27])\n                5'b0_0000,                                         // srli\n                5'b0_1000: illegal_insn = 1'b0;                    // srai\n                5'b0_0100,                                         // sroi\n                5'b0_1100,                                         // rori\n                5'b0_1001: illegal_insn = RV32B ? 1'b0 : 1'b1;     // sbexti\n                5'b0_1101,                                         // grevi\n                5'b0_0101: illegal_insn = RV32B ? 1'b0 : 1'b1;     // gorci\n                5'b0_0001: if (instr[26] == 1'b0) begin\n                  illegal_insn = RV32B ? 1'b0 : 1'b1;              // unshfl\n                end else begin\n                  illegal_insn = 1'b1;\n                end\n                default: illegal_insn = 1'b1;\n              endcase\n            end\n          end\n          default: illegal_insn = 1'b1;\n        endcase\n      end\n      OPCODE_OP: begin  // Register-Register ALU operation\n        rf_ren_a_o      = 1'b1;\n        rf_ren_b_o      = 1'b1;\n        rf_we           = 1'b1;\n        if ({instr[26], instr[13:12]} == {1'b1, 2'b01}) begin\n          illegal_insn = RV32B ? 1'b0 : 1'b1; // cmix / cmov / fsl / fsr\n        end else begin\n          unique case ({instr[31:25], instr[14:12]})\n            // RV32I ALU operations\n            {7'b000_0000, 3'b000},\n            {7'b010_0000, 3'b000},\n            {7'b000_0000, 3'b010},\n            {7'b000_0000, 3'b011},\n            {7'b000_0000, 3'b100},\n            {7'b000_0000, 3'b110},\n            {7'b000_0000, 3'b111},\n            {7'b000_0000, 3'b001},\n            {7'b000_0000, 3'b101},\n            {7'b010_0000, 3'b101}: illegal_insn = 1'b0;\n            // RV32B zbb\n            {7'b010_0000, 3'b111}, // andn\n            {7'b010_0000, 3'b110}, // orn\n            {7'b010_0000, 3'b100}, // xnor\n            {7'b001_0000, 3'b001}, // slo\n            {7'b001_0000, 3'b101}, // sro\n            {7'b011_0000, 3'b001}, // rol\n            {7'b011_0000, 3'b101}, // ror\n            {7'b000_0101, 3'b100}, // min\n            {7'b000_0101, 3'b101}, // max\n            {7'b000_0101, 3'b110}, // minu\n            {7'b000_0101, 3'b111}, // maxu\n            {7'b000_0100, 3'b100}, // pack\n            {7'b010_0100, 3'b100}, // packu\n            {7'b000_0100, 3'b111}, // packh\n            // RV32B zbs\n            {7'b010_0100, 3'b001}, // sbclr\n            {7'b001_0100, 3'b001}, // sbset\n            {7'b011_0100, 3'b001}, // sbinv\n            {7'b010_0100, 3'b101}, // sbext\n            // RV32B zbe\n            {7'b010_0100, 3'b110}, // bdep\n            {7'b000_0100, 3'b110}, // bext\n            // RV32B zbp\n            {7'b011_0100, 3'b101}, // grev\n            {7'b001_0100, 3'b101}, // gorc\n            {7'b000_0100, 3'b001}, // shfl\n            {7'b000_0100, 3'b101}, // unshfl\n            // RV32B zbf\n            {7'b010_0100, 3'b111}, // bfp\n            // RV32B zbc\n            {7'b000_0101, 3'b001}, // clmul\n            {7'b000_0101, 3'b010}, // clmulr\n            {7'b000_0101, 3'b011}: illegal_insn = RV32B ? 1'b0 : 1'b1; // clmulh\n            // RV32M instructions\n            {7'b000_0001, 3'b000}: begin // mul\n              multdiv_operator_o    = MD_OP_MULL;\n              multdiv_signed_mode_o = 2'b00;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b001}: begin // mulh\n              multdiv_operator_o    = MD_OP_MULH;\n              multdiv_signed_mode_o = 2'b11;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b010}: begin // mulhsu\n              multdiv_operator_o    = MD_OP_MULH;\n              multdiv_signed_mode_o = 2'b01;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b011}: begin // mulhu\n              multdiv_operator_o    = MD_OP_MULH;\n              multdiv_signed_mode_o = 2'b00;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b100}: begin // div\n              multdiv_operator_o    = MD_OP_DIV;\n              multdiv_signed_mode_o = 2'b11;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b101}: begin // divu\n              multdiv_operator_o    = MD_OP_DIV;\n              multdiv_signed_mode_o = 2'b00;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b110}: begin // rem\n              multdiv_operator_o    = MD_OP_REM;\n              multdiv_signed_mode_o = 2'b11;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            {7'b000_0001, 3'b111}: begin // remu\n              multdiv_operator_o    = MD_OP_REM;\n              multdiv_signed_mode_o = 2'b00;\n              illegal_insn          = RV32M ? 1'b0 : 1'b1;\n            end\n            default: begin\n              illegal_insn = 1'b1;\n            end\n          endcase\n        end\n      end\n      /////////////\n      // Special //\n      /////////////\n      OPCODE_MISC_MEM: begin\n        // For now, treat the FENCE (funct3 == 000) instruction as a NOP.  This may not be correct\n        // in a system with caches and should be revisited.\n        // FENCE.I will flush the IF stage and prefetch buffer (or ICache) but nothing else.\n        unique case (instr[14:12])\n          3'b000: begin\n            rf_we           = 1'b0;\n          end\n          3'b001: begin\n            // FENCE.I is implemented as a jump to the next PC, this gives the required flushing\n            // behaviour (iside prefetch buffer flushed and response to any outstanding iside\n            // requests will be ignored).\n            // If present, the ICache will also be flushed.\n            jump_in_dec_o   = 1'b1;\n            rf_we           = 1'b0;\n            if (instr_first_cycle_i) begin\n              jump_set_o       = 1'b1;\n              icache_inval_o   = 1'b1;\n            end\n          end\n          default: begin\n            illegal_insn       = 1'b1;\n          end\n        endcase\n      end\n      OPCODE_SYSTEM: begin\n        if (instr[14:12] == 3'b000) begin\n          // non CSR related SYSTEM instructions\n          unique case (instr[31:20])\n            12'h000:  // ECALL\n              // environment (system) call\n              ecall_insn_o = 1'b1;\n            12'h001:  // ebreak\n              // debugger trap\n              ebrk_insn_o = 1'b1;\n            12'h302:  // mret\n              mret_insn_o = 1'b1;\n            12'h7b2:  // dret\n              dret_insn_o = 1'b1;\n            12'h105:  // wfi\n              wfi_insn_o = 1'b1;\n            default:\n              illegal_insn = 1'b1;\n          endcase\n          // rs1 and rd must be 0\n          if (instr[19:15] != 5'b0 || instr[11:07] != 5'b0) begin\n            illegal_insn = 1'b1;\n          end\n        end else begin\n          // instruction to read/modify CSR\n          csr_access_o     = 1'b1;\n          rf_wdata_sel_o   = RF_WD_CSR;\n          rf_we            = 1'b1;\n          if (~instr[14]) begin\n            rf_ren_a_o         = 1'b1;\n          end\n          unique case (instr[13:12])\n            2'b01:   csr_op = CSR_OP_WRITE;\n            2'b10:   csr_op = CSR_OP_SET;\n            2'b11:   csr_op = CSR_OP_CLEAR;\n            default: csr_illegal = 1'b1;\n          endcase\n          illegal_insn = csr_illegal;\n        end\n      end\n      default: begin\n        illegal_insn = 1'b1;\n      end\n    endcase\n    // make sure illegal compressed instructions cause illegal instruction exceptions\n    if (illegal_c_insn_i) begin\n      illegal_insn = 1'b1;\n    end\n    // make sure illegal instructions detected in the decoder do not propagate from decoder\n    // into register file, LSU, EX, WB, CSRs, PC\n    // NOTE: instructions can also be detected to be illegal inside the CSRs (upon accesses with\n    // insufficient privileges), or when accessing non-available registers in RV32E,\n    // these cases are not handled here\n    if (illegal_insn) begin\n      rf_we           = 1'b0;\n      data_req_o      = 1'b0;\n      data_we_o       = 1'b0;\n      jump_in_dec_o   = 1'b0;\n      jump_set_o      = 1'b0;\n      branch_in_dec_o = 1'b0;\n      csr_access_o    = 1'b0;\n    end\n  end\n  /////////////////////////////\n  // Decoder for ALU control //\n  /////////////////////////////\n  always_comb begin\n    alu_operator_o     = ALU_SLTU;\n    alu_op_a_mux_sel_o = OP_A_IMM;\n    alu_op_b_mux_sel_o = OP_B_IMM;\n    imm_a_mux_sel_o    = IMM_A_ZERO;\n    imm_b_mux_sel_o    = IMM_B_I;\n    bt_a_mux_sel_o     = OP_A_CURRPC;\n    bt_b_mux_sel_o     = IMM_B_I;\n    opcode_alu         = opcode_e'(instr_alu[6:0]);\n    use_rs3            = 1'b0;\n    alu_multicycle_o   = 1'b0;\n    mult_sel_o         = 1'b0;\n    div_sel_o          = 1'b0;\n    unique case (opcode_alu)\n      ///////////\n      // Jumps //\n      ///////////\n      OPCODE_JAL: begin // Jump and Link\n        if (BranchTargetALU) begin\n          bt_a_mux_sel_o = OP_A_CURRPC;\n          bt_b_mux_sel_o = IMM_B_J;\n        end\n        // Jumps take two cycles without the BTALU\n        if (instr_first_cycle_i && !BranchTargetALU) begin\n          // Calculate jump target\n          alu_op_a_mux_sel_o  = OP_A_CURRPC;\n          alu_op_b_mux_sel_o  = OP_B_IMM;\n          imm_b_mux_sel_o     = IMM_B_J;\n          alu_operator_o      = ALU_ADD;\n        end else begin\n          // Calculate and store PC+4\n          alu_op_a_mux_sel_o  = OP_A_CURRPC;\n          alu_op_b_mux_sel_o  = OP_B_IMM;\n          imm_b_mux_sel_o     = IMM_B_INCR_PC;\n          alu_operator_o      = ALU_ADD;\n        end\n      end\n      OPCODE_JALR: begin // Jump and Link Register\n        if (BranchTargetALU) begin\n          bt_a_mux_sel_o = OP_A_REG_A;\n          bt_b_mux_sel_o = IMM_B_I;\n        end\n        // Jumps take two cycles without the BTALU\n        if (instr_first_cycle_i && !BranchTargetALU) begin\n          // Calculate jump target\n          alu_op_a_mux_sel_o  = OP_A_REG_A;\n          alu_op_b_mux_sel_o  = OP_B_IMM;\n          imm_b_mux_sel_o     = IMM_B_I;\n          alu_operator_o      = ALU_ADD;\n        end else begin\n          // Calculate and store PC+4\n          alu_op_a_mux_sel_o  = OP_A_CURRPC;\n          alu_op_b_mux_sel_o  = OP_B_IMM;\n          imm_b_mux_sel_o     = IMM_B_INCR_PC;\n          alu_operator_o      = ALU_ADD;\n        end\n      end\n      OPCODE_BRANCH: begin // Branch\n        // Check branch condition selection\n        unique case (instr_alu[14:12])\n          3'b000:  alu_operator_o = ALU_EQ;\n          3'b001:  alu_operator_o = ALU_NE;\n          3'b100:  alu_operator_o = ALU_LT;\n          3'b101:  alu_operator_o = ALU_GE;\n          3'b110:  alu_operator_o = ALU_LTU;\n          3'b111:  alu_operator_o = ALU_GEU;\n          default: ;\n        endcase\n        if (BranchTargetALU) begin\n          bt_a_mux_sel_o = OP_A_CURRPC;\n          // Not-taken branch will jump to next instruction (used in secure mode)\n          bt_b_mux_sel_o = branch_taken_i ? IMM_B_B : IMM_B_INCR_PC;\n        end\n        // Without branch target ALU, a branch is a two-stage operation using the Main ALU in both\n        // stages\n        if (instr_first_cycle_i) begin\n          // First evaluate the branch condition\n          alu_op_a_mux_sel_o  = OP_A_REG_A;\n          alu_op_b_mux_sel_o  = OP_B_REG_B;\n        end else begin\n          // Then calculate jump target\n          alu_op_a_mux_sel_o  = OP_A_CURRPC;\n          alu_op_b_mux_sel_o  = OP_B_IMM;\n          // Not-taken branch will jump to next instruction (used in secure mode)\n          imm_b_mux_sel_o     = branch_taken_i ? IMM_B_B : IMM_B_INCR_PC;\n          alu_operator_o      = ALU_ADD;\n        end\n      end\n      ////////////////\n      // Load/store //\n      ////////////////\n      OPCODE_STORE: begin\n        alu_op_a_mux_sel_o = OP_A_REG_A;\n        alu_op_b_mux_sel_o = OP_B_REG_B;\n        alu_operator_o     = ALU_ADD;\n        if (!instr_alu[14]) begin\n          // offset from immediate\n          imm_b_mux_sel_o     = IMM_B_S;\n          alu_op_b_mux_sel_o  = OP_B_IMM;\n        end\n      end\n      OPCODE_LOAD: begin\n        alu_op_a_mux_sel_o  = OP_A_REG_A;\n        // offset from immediate\n        alu_operator_o      = ALU_ADD;\n        alu_op_b_mux_sel_o  = OP_B_IMM;\n        imm_b_mux_sel_o     = IMM_B_I;\n      end\n      /////////\n      // ALU //\n      /////////\n      OPCODE_LUI: begin  // Load Upper Immediate\n        alu_op_a_mux_sel_o  = OP_A_IMM;\n        alu_op_b_mux_sel_o  = OP_B_IMM;\n        imm_a_mux_sel_o     = IMM_A_ZERO;\n        imm_b_mux_sel_o     = IMM_B_U;\n        alu_operator_o      = ALU_ADD;\n      end\n      OPCODE_AUIPC: begin  // Add Upper Immediate to PC\n        alu_op_a_mux_sel_o  = OP_A_CURRPC;\n        alu_op_b_mux_sel_o  = OP_B_IMM;\n        imm_b_mux_sel_o     = IMM_B_U;\n        alu_operator_o      = ALU_ADD;\n      end\n      OPCODE_OP_IMM: begin // Register-Immediate ALU Operations\n        alu_op_a_mux_sel_o  = OP_A_REG_A;\n        alu_op_b_mux_sel_o  = OP_B_IMM;\n        imm_b_mux_sel_o     = IMM_B_I;\n        unique case (instr_alu[14:12])\n          3'b000: alu_operator_o = ALU_ADD;  // Add Immediate\n          3'b010: alu_operator_o = ALU_SLT;  // Set to one if Lower Than Immediate\n          3'b011: alu_operator_o = ALU_SLTU; // Set to one if Lower Than Immediate Unsigned\n          3'b100: alu_operator_o = ALU_XOR;  // Exclusive Or with Immediate\n          3'b110: alu_operator_o = ALU_OR;   // Or with Immediate\n          3'b111: alu_operator_o = ALU_AND;  // And with Immediate\n          3'b001: begin\n            if (RV32B) begin\n              unique case (instr_alu[31:27])\n                5'b0_0000: alu_operator_o = ALU_SLL;    // Shift Left Logical by Immediate\n                5'b0_0100: alu_operator_o = ALU_SLO;    // Shift Left Ones by Immediate\n                5'b0_1001: alu_operator_o = ALU_SBCLR;  // Clear bit specified by immediate\n                5'b0_0101: alu_operator_o = ALU_SBSET;  // Set bit specified by immediate\n                5'b0_1101: alu_operator_o = ALU_SBINV;  // Invert bit specified by immediate.\n                // Shuffle with Immediate Control Value\n                5'b0_0001: if (instr_alu[26] == 0) alu_operator_o = ALU_SHFL;\n                5'b0_1100: begin\n                  unique case (instr_alu[26:20])\n                    7'b000_0000: alu_operator_o = ALU_CLZ;      // clz\n                    7'b000_0001: alu_operator_o = ALU_CTZ;      // ctz\n                    7'b000_0010: alu_operator_o = ALU_PCNT;     // pcnt\n                    7'b000_0100: alu_operator_o = ALU_SEXTB;    // sext.b\n                    7'b000_0101: alu_operator_o = ALU_SEXTH;    // sext.h\n                    7'b001_0000: begin\n                      alu_operator_o = ALU_CRC32_B;  // crc32.b\n                      alu_multicycle_o = 1'b1;\n                    end\n                    7'b001_0001: begin\n                      alu_operator_o = ALU_CRC32_H;  // crc32.h\n                      alu_multicycle_o = 1'b1;\n                    end\n                    7'b001_0010: begin\n                      alu_operator_o = ALU_CRC32_W;  // crc32.w\n                      alu_multicycle_o = 1'b1;\n                    end\n                    7'b001_1000: begin\n                      alu_operator_o = ALU_CRC32C_B; // crc32c.b\n                      alu_multicycle_o = 1'b1;\n                    end\n                    7'b001_1001: begin\n                      alu_operator_o = ALU_CRC32C_H; // crc32c.h\n                      alu_multicycle_o = 1'b1;\n                    end\n                    7'b001_1010: begin\n                      alu_operator_o = ALU_CRC32C_W; // crc32c.w\n                      alu_multicycle_o = 1'b1;\n                    end\n                    default: ;\n                  endcase\n                end\n                default: ;\n              endcase\n            end else begin\n              alu_operator_o = ALU_SLL;                 // Shift Left Logical by Immediate\n            end\n          end\n          3'b101: begin\n            if (RV32B) begin\n              if (instr_alu[26] == 1'b1) begin\n                alu_operator_o = ALU_FSR;\n                alu_multicycle_o = 1'b1;\n                if (instr_first_cycle_i) begin\n                  use_rs3 = 1'b0;\n                end else begin\n                  use_rs3 = 1'b1;\n                end\n              end else begin\n                unique case (instr_alu[31:27])\n                  5'b0_0000: alu_operator_o = ALU_SRL;   // Shift Right Logical by Immediate\n                  5'b0_1000: alu_operator_o = ALU_SRA;   // Shift Right Arithmetically by Immediate\n                  5'b0_0100: alu_operator_o = ALU_SRO;   // Shift Right Ones by Immediate\n                  5'b0_1001: alu_operator_o = ALU_SBEXT; // Extract bit specified by immediate.\n                  5'b0_1100: begin\n                    alu_operator_o = ALU_ROR;           // Rotate Right by Immediate\n                    alu_multicycle_o = 1'b1;\n                  end\n                  5'b0_1101: alu_operator_o = ALU_GREV; // General Reverse with Imm Control Val\n                  5'b0_0101: alu_operator_o = ALU_GORC; // General Or-combine with Imm Control Val\n                  // Unshuffle with Immediate Control Value\n                  5'b0_0001: if (instr_alu[26] == 1'b0) alu_operator_o = ALU_UNSHFL;\n                  default: ;\n                endcase\n              end\n            end else begin\n              if (instr_alu[31:27] == 5'b0_0000) begin\n                alu_operator_o = ALU_SRL;              // Shift Right Logical by Immediate\n              end else if (instr_alu[31:27] == 5'b0_1000) begin\n                alu_operator_o = ALU_SRA;              // Shift Right Arithmetically by Immediate\n              end\n            end\n          end\n          default: ;\n        endcase\n      end\n      OPCODE_OP: begin  // Register-Register ALU operation\n        alu_op_a_mux_sel_o = OP_A_REG_A;\n        alu_op_b_mux_sel_o = OP_B_REG_B;\n        if (instr_alu[26]) begin\n          if (RV32B) begin\n            unique case ({instr_alu[26:25], instr_alu[14:12]})\n              {2'b11, 3'b001}: begin\n                alu_operator_o   = ALU_CMIX; // cmix\n                alu_multicycle_o = 1'b1;\n                if (instr_first_cycle_i) begin\n                  use_rs3 = 1'b0;\n                end else begin\n                  use_rs3 = 1'b1;\n                end\n              end\n              {2'b11, 3'b101}: begin\n                alu_operator_o   = ALU_CMOV; // cmov\n                alu_multicycle_o = 1'b1;\n                if (instr_first_cycle_i) begin\n                  use_rs3 = 1'b0;\n                end else begin\n                  use_rs3 = 1'b1;\n                end\n              end\n              {2'b10, 3'b001}: begin\n                alu_operator_o   = ALU_FSL;  // fsl\n                alu_multicycle_o = 1'b1;\n                if (instr_first_cycle_i) begin\n                  use_rs3 = 1'b0;\n                end else begin\n                  use_rs3 = 1'b1;\n                end\n              end\n              {2'b10, 3'b101}: begin\n                alu_operator_o   = ALU_FSR;  // fsr\n                alu_multicycle_o = 1'b1;\n                if (instr_first_cycle_i) begin\n                  use_rs3 = 1'b0;\n                end else begin\n                  use_rs3 = 1'b1;\n                end\n              end\n              default: ;\n            endcase\n          end\n        end else begin\n          unique case ({instr_alu[31:25], instr_alu[14:12]})\n            // RV32I ALU operations\n            {7'b000_0000, 3'b000}: alu_operator_o = ALU_ADD;   // Add\n            {7'b010_0000, 3'b000}: alu_operator_o = ALU_SUB;   // Sub\n            {7'b000_0000, 3'b010}: alu_operator_o = ALU_SLT;   // Set Lower Than\n            {7'b000_0000, 3'b011}: alu_operator_o = ALU_SLTU;  // Set Lower Than Unsigned\n            {7'b000_0000, 3'b100}: alu_operator_o = ALU_XOR;   // Xor\n            {7'b000_0000, 3'b110}: alu_operator_o = ALU_OR;    // Or\n            {7'b000_0000, 3'b111}: alu_operator_o = ALU_AND;   // And\n            {7'b000_0000, 3'b001}: alu_operator_o = ALU_SLL;   // Shift Left Logical\n            {7'b000_0000, 3'b101}: alu_operator_o = ALU_SRL;   // Shift Right Logical\n            {7'b010_0000, 3'b101}: alu_operator_o = ALU_SRA;   // Shift Right Arithmetic\n            // RV32B ALU Operations\n            {7'b001_0000, 3'b001}: if (RV32B) alu_operator_o = ALU_SLO;   // slo\n            {7'b001_0000, 3'b101}: if (RV32B) alu_operator_o = ALU_SRO;   // sro\n            {7'b011_0000, 3'b001}: begin\n              if (RV32B) begin\n                alu_operator_o = ALU_ROL;   // rol\n                alu_multicycle_o = 1'b1;\n              end\n            end\n            {7'b011_0000, 3'b101}: begin\n              if (RV32B) begin\n                alu_operator_o = ALU_ROR;   // ror\n                alu_multicycle_o = 1'b1;\n              end\n            end\n            {7'b000_0101, 3'b100}: if (RV32B) alu_operator_o = ALU_MIN;    // min\n            {7'b000_0101, 3'b101}: if (RV32B) alu_operator_o = ALU_MAX;    // max\n            {7'b000_0101, 3'b110}: if (RV32B) alu_operator_o = ALU_MINU;   // minu\n            {7'b000_0101, 3'b111}: if (RV32B) alu_operator_o = ALU_MAXU;   // maxu\n            {7'b000_0100, 3'b100}: if (RV32B) alu_operator_o = ALU_PACK;   // pack\n            {7'b010_0100, 3'b100}: if (RV32B) alu_operator_o = ALU_PACKU;  // packu\n            {7'b000_0100, 3'b111}: if (RV32B) alu_operator_o = ALU_PACKH;  // packh\n            {7'b010_0000, 3'b100}: if (RV32B) alu_operator_o = ALU_XNOR;   // xnor\n            {7'b010_0000, 3'b110}: if (RV32B) alu_operator_o = ALU_ORN;    // orn\n            {7'b010_0000, 3'b111}: if (RV32B) alu_operator_o = ALU_ANDN;   // andn\n            // RV32B zbp\n            {7'b011_0100, 3'b101}: if (RV32B) alu_operator_o = ALU_GREV;   // grev\n            {7'b001_0100, 3'b101}: if (RV32B) alu_operator_o = ALU_GORC;   // grev\n            {7'b000_0100, 3'b001}: if (RV32B) alu_operator_o = ALU_SHFL;   // shfl\n            {7'b000_0100, 3'b101}: if (RV32B) alu_operator_o = ALU_UNSHFL; // unshfl\n            // RV32B zbs\n            {7'b010_0100, 3'b001}: if (RV32B) alu_operator_o = ALU_SBCLR;  // sbclr\n            {7'b001_0100, 3'b001}: if (RV32B) alu_operator_o = ALU_SBSET;  // sbset\n            {7'b011_0100, 3'b001}: if (RV32B) alu_operator_o = ALU_SBINV;  // sbinv\n            {7'b010_0100, 3'b101}: if (RV32B) alu_operator_o = ALU_SBEXT;  // sbext\n            // RV32B zbc\n            {7'b000_0101, 3'b001}: if (RV32B) alu_operator_o = ALU_CLMUL;  // clmul\n            {7'b000_0101, 3'b010}: if (RV32B) alu_operator_o = ALU_CLMULR; // clmulr\n            {7'b000_0101, 3'b011}: if (RV32B) alu_operator_o = ALU_CLMULH; // clmulh\n            // RV32B zbe\n            {7'b010_0100, 3'b110}: if (RV32B) alu_operator_o = ALU_BDEP;   // bdep\n            {7'b000_0100, 3'b110}: if (RV32B) alu_operator_o = ALU_BEXT;   // bext\n            // RV32B zbf\n            {7'b010_0100, 3'b111}: if (RV32B) alu_operator_o = ALU_BFP;    // bfp\n            // RV32M instructions, all use the same ALU operation\n            {7'b000_0001, 3'b000}: begin // mul\n              alu_operator_o = ALU_ADD;\n              mult_sel_o     = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b001}: begin // mulh\n              alu_operator_o = ALU_ADD;\n              mult_sel_o     = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b010}: begin // mulhsu\n              alu_operator_o = ALU_ADD;\n              mult_sel_o     = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b011}: begin // mulhu\n              alu_operator_o = ALU_ADD;\n              mult_sel_o     = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b100}: begin // div\n              alu_operator_o = ALU_ADD;\n              div_sel_o      = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b101}: begin // divu\n              alu_operator_o = ALU_ADD;\n              div_sel_o      = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b110}: begin // rem\n              alu_operator_o = ALU_ADD;\n              div_sel_o      = RV32M ? 1'b1 : 1'b0;\n            end\n            {7'b000_0001, 3'b111}: begin // remu\n              alu_operator_o = ALU_ADD;\n              div_sel_o      = RV32M ? 1'b1 : 1'b0;\n            end\n            default: ;\n          endcase\n        end\n      end\n      /////////////\n      // Special //\n      /////////////\n      OPCODE_MISC_MEM: begin\n        // For now, treat the FENCE (funct3 == 000) instruction as a NOP.  This may not be correct\n        // in a system with caches and should be revisited.\n        // FENCE.I will flush the IF stage and prefetch buffer but nothing else.\n        unique case (instr_alu[14:12])\n          3'b000: begin\n            alu_operator_o     = ALU_ADD; // nop\n            alu_op_a_mux_sel_o = OP_A_REG_A;\n            alu_op_b_mux_sel_o = OP_B_IMM;\n          end\n          3'b001: begin\n            if (BranchTargetALU) begin\n              bt_a_mux_sel_o     = OP_A_CURRPC;\n              bt_b_mux_sel_o     = IMM_B_INCR_PC;\n            end else begin\n              alu_op_a_mux_sel_o = OP_A_CURRPC;\n              alu_op_b_mux_sel_o = OP_B_IMM;\n              imm_b_mux_sel_o    = IMM_B_INCR_PC;\n              alu_operator_o     = ALU_ADD;\n            end\n          end\n          default: ;\n        endcase\n      end\n      OPCODE_SYSTEM: begin\n        if (instr_alu[14:12] == 3'b000) begin\n          // non CSR related SYSTEM instructions\n          alu_op_a_mux_sel_o = OP_A_REG_A;\n          alu_op_b_mux_sel_o = OP_B_IMM;\n        end else begin\n          // instruction to read/modify CSR\n          alu_op_b_mux_sel_o = OP_B_IMM;\n          imm_a_mux_sel_o    = IMM_A_Z;\n          imm_b_mux_sel_o    = IMM_B_I;  // CSR address is encoded in I imm\n          if (instr_alu[14]) begin\n            // rs1 field is used as immediate\n            alu_op_a_mux_sel_o = OP_A_IMM;\n          end else begin\n            alu_op_a_mux_sel_o = OP_A_REG_A;\n          end\n        end\n      end\n      default: ;\n    endcase\n  end\n  // do not enable multdiv in case of illegal instruction exceptions\n  assign mult_en_o = illegal_insn ? 1'b0 : mult_sel_o;\n  assign div_en_o  = illegal_insn ? 1'b0 : div_sel_o;\n  // make sure instructions accessing non-available registers in RV32E cause illegal\n  // instruction exceptions\n  assign illegal_insn_o = illegal_insn | illegal_reg_rv32e;\n  // do not propgate regfile write enable if non-available registers are accessed in RV32E\n  assign rf_we_o = rf_we & ~illegal_reg_rv32e;\n  ////////////////\n  // Assertions //\n  ////////////////\n  // Selectors must be known/valid.\n  \nendmodule // controller\n");
